ount":{"login":"fbourasse","providerType":"User"},"email":"fbourasse@jahia.com","name":"Florent BOURASSÉ"},"authoredDate":"2026-06-22T14:55:45Z","committedDate":"2026-06-22T14:55:45Z","committer":{"account":{"login":"web-flow","providerType":"User"},"email":"noreply@github.com","name":"GitHub"},"observedAt":"2026-10-08T17:48:55.019Z","repositoryId":433977737,"sha":"4e3ed142b8f5ae1b46dbf0cfa90bd2686d3cd64d"},{"author":{"account":{"login":"fbourasse","providerType":"User"},"email":"fbourasse@jahia.com","name":"Florent BOURASSÉ"},"authoredDate":"2026-06-22T10:08:12Z","committedDate":"2026-06-22T10:08:12Z","committer":{"account":{"login":"web-flow","providerType":"User"},"email":"noreply@github.com","name":"GitHub"},"observedAt":"2026-10-08T17:48:55.019Z","repositoryId":433977737,"sha":"bf87280208b045eada3fc11be68ea4cbd76618f7"},{"author":{"account":{"login":"fbourasse","providerType":"User"},"email":"fbourasse@jahia.com","name":"Florent BOURASSÉ"},"authoredDate":"2026-06-20T17:31:00Z","committedDate":"2026-06-20T17:31:00Z","committer":{"account":{"login":"web-flow","providerType":"User"},"email":"noreply@github.com","name":"GitHub"},"observedAt":"2026-10-08T17:48:55.019Z","repositoryId":433977737,"sha":"52439dffe9548c87fbdf14ce39460e7a5fc596c8"},{"author":{"account":{"login":"fbourasse","providerType":"User"},"email":"fbourasse@jahia.com","name":"Florent BOURASSE"},"authoredDate":"2025-07-30T07:54:25Z","committedDate":"2025-07-30T07:54:25Z","committer":{"account":{"login":"fbourasse","providerType":"User"},"email":"fbourasse@jahia.com","name":"Florent BOURASSE"},"observedAt":"2026-10-08T17:48:55.019Z","repositoryId":433977737,"sha":"eb6cfc4fa103d794f9dacce98c1be7d43feabf4c"},{"author":{"account":{"login":"fbourasse","providerType":"User"},"email":"fbourasse@jahia.com","name":"Florent BOURASSE"},"authoredDate":"2025-07-30T07:54:20Z","committedDate":"2025-07-30T07:54:20Z","committer":{"account":{"login":"fbourasse","providerType":"User"},"email":"fbourasse@jahia.com","na